import { useRole } from "../../context/RoleContext";
import { useNavigate, useLocation } from "react-router-dom";

// Breadcrumb definitions per route
const getBreadcrumbs = (pathname, role) => {
  const jobId = pathname.split("/")[2];

  const recruiterCrumbs = {
    "/job-setup":          [{ label: "Home", path: "/" }, { label: "Job Setup" }],
    [`/upload/${jobId}`]:  [{ label: "Home", path: "/" }, { label: "Job Setup", path: "/job-setup" }, { label: "Upload CVs" }],
    [`/results/${jobId}`]: [{ label: "Home", path: "/" }, { label: "Job Setup", path: "/job-setup" }, { label: "Upload CVs", path: `/upload/${jobId}` }, { label: "Results" }],
    [`/shortlist/${jobId}`]: [{ label: "Home", path: "/" }, { label: "Job Setup", path: "/job-setup" }, { label: "Results", path: `/results/${jobId}` }, { label: "Shortlist" }],
  };

  const hmCrumbs = {
    "/hm-dashboard":         [{ label: "Home", path: "/" }, { label: "Dashboard" }],
    [`/hm-review/${jobId}`]: [{ label: "Home", path: "/" }, { label: "Dashboard", path: "/hm-dashboard" }, { label: "Shortlist" }],
    [`/results/${jobId}`]:   [{ label: "Home", path: "/" }, { label: "Dashboard", path: "/hm-dashboard" }, { label: "Results" }],
  };

  const crumbMap = role === "hiring_manager" ? hmCrumbs : recruiterCrumbs;
  return crumbMap[pathname] || [{ label: "Home", path: "/" }];
};

export default function Layout({ children }) {
  const { role, setRole } = useRole();
  const navigate = useNavigate();
  const location = useLocation();
  const crumbs = getBreadcrumbs(location.pathname, role);

  return (
    <div style={{ minHeight: "100vh", background: "var(--navy)" }}>
      {/* Top nav */}
      <nav style={{
        background: "rgba(10,15,30,0.9)",
        backdropFilter: "blur(12px)",
        borderBottom: "1px solid var(--border)",
        padding: "0 32px",
        height: 64,
        display: "flex",
        alignItems: "center",
        justifyContent: "space-between",
        position: "sticky",
        top: 0,
        zIndex: 100,
      }}>
        {/* Logo */}
        <div style={{ display: "flex", alignItems: "center", gap: 12, cursor: "pointer" }}
          onClick={() => navigate("/")}>
          <div style={{
            width: 32, height: 32, borderRadius: 8,
            background: "var(--blue)",
            display: "flex", alignItems: "center", justifyContent: "center",
            fontSize: 16, fontWeight: 800, fontFamily: "Plus Jakarta Sans", color: "white",
          }}>P</div>
          <span style={{ fontFamily: "Plus Jakarta Sans", fontWeight: 700, fontSize: 16, color: "var(--text-primary)" }}>
            PassiveTalent
          </span>
        </div>

        {/* Role badge + switch */}
        <div style={{ display: "flex", alignItems: "center", gap: 16 }}>
          <span className="badge badge-blue">
            {role === "recruiter" ? "Recruiter" : "Hiring Manager"}
          </span>
          <button className="btn-secondary" style={{ padding: "8px 16px", fontSize: 13 }}
            onClick={() => { setRole(null); navigate("/"); }}>
            Switch Role
          </button>
        </div>
      </nav>

      {/* Breadcrumb bar */}
      {crumbs.length > 1 && (
        <div style={{
          background: "rgba(10,15,30,0.6)",
          borderBottom: "1px solid var(--border)",
          padding: "10px 32px",
          display: "flex",
          alignItems: "center",
          gap: 8,
        }}>
          {crumbs.map((crumb, i) => (
            <div key={i} style={{ display: "flex", alignItems: "center", gap: 8 }}>
              {i > 0 && <span style={{ color: "var(--text-muted)", fontSize: 12 }}>›</span>}
              {crumb.path ? (
                <button onClick={() => navigate(crumb.path)} style={{
                  background: "none", border: "none", cursor: "pointer",
                  color: "var(--blue)", fontSize: 13,
                  fontFamily: "Plus Jakarta Sans", fontWeight: 500,
                  padding: 0,
                }}>{crumb.label}</button>
              ) : (
                <span style={{ color: "var(--text-primary)", fontSize: 13, fontFamily: "Plus Jakarta Sans", fontWeight: 600 }}>
                  {crumb.label}
                </span>
              )}
            </div>
          ))}
        </div>
      )}

      {/* Page content */}
      <main style={{ maxWidth: 1200, margin: "0 auto", padding: "40px 32px" }}>
        {children}
      </main>
    </div>
  );
}
